    private static func generateCountryEvents(forCode upper: String) -> [NativeCampaignEvent] {
        let lower = upper.lowercased()
        let countryName = CountryCatalog.all.first { $0.code == upper }?.name ?? upper
        let stateVerbs = [
            "Direct Sovereign Credit to",
            "Enact National Charter for",
            "Mobilize State Capacity for",
            "Authorize Executive Mandate on",
            "Capitalize Public Authority for"
        ]
        let partnerVerbs = [
            "Charter Commercial Syndicate for",
            "Open Multilateral Clearing on",
            "License Regional Consortium for",
            "Co-Finance Private Tenders on",
            "Broker Stakeholder Compact on"
        ]

        var list: [NativeCampaignEvent] = []
        list.reserveCapacity(100)

        for (index, theme) in eventThemes.enumerated() {
            let num = index + 1
            let id = "evt-\(lower)-\(String(format: "%03d", num))"
            let year = 2010 + (index * 35) / 100
            let month = 1 + (index * 7) % 12
            let day = 1 + (index * 13) % 28
            let date = String(format: "%04d-%02d-%02d", year, month, day)

            let chainNext: String? = (num % 5 != 0) ? "evt-\(lower)-\(String(format: "%03d", num + 1))" : nil
            let verbA = stateVerbs[index % stateVerbs.count]
            let verbB = partnerVerbs[index % partnerVerbs.count]
            let loweredDesc = theme.desc.prefix(1).lowercased() + theme.desc.dropFirst()

            let event = NativeCampaignEvent(
                date: date,
                description: "\(countryName): \(theme.desc) Executive council directs emergency policy formulation to secure long-term sovereign autonomy.",
                id: id,
                importance: theme.importance,
                kind: .action,
                linkedActionIDs: [],
                notable: true,
                playerRelated: true,
                strategicEffects: [
                    NativeStrategicEffect(
                        date: date,
                        eventId: id,
                        id: "\(id)-effect",
                        magnitude: 8,
                        summary: "\(countryName) adapts to \(theme.title.lowercased()) with structural policy reforms.",
                        target: upper,
                        track: theme.track
                    )
                ],
                title: "\(countryName): \(theme.title)",
                hexLeverCode: theme.tokenA,
                imageAssetName: theme.image,
                decisionOptions: [
                    NativeEventDecisionOption(
                        id: "\(id)-opt-a",
                        label: "\(verbA) \(theme.title)",
                        detail: "Commit \(countryName)'s central treasury and ministries to execute \(theme.title.lowercased()) while \(loweredDesc) [\(theme.tokenA) +10, \(theme.tokenB) +4]",
                        effectTrack: theme.track,
                        effectMagnitude: 10,
                        nextChainedEventID: chainNext,
                        setFlag: "flag-\(id)-a"
                    ),
                    NativeEventDecisionOption(
                        id: "\(id)-opt-b",
                        label: "\(verbB) \(theme.title)",
                        detail: "Coordinate \(countryName)'s commercial syndicates and regional partners around \(theme.title.lowercased()) while \(loweredDesc) [\(theme.tokenB) +8, \(theme.tokenA) +3]",
                        effectTrack: .marketConfidence,
                        effectMagnitude: 8,
                        nextChainedEventID: chainNext,
                        setFlag: "flag-\(id)-b"
                    )
                ],
                chainedEventID: chainNext
            )
            list.append(event)
        }

        return list
    }
}
